REGULARIZATION_LOCATION_NAME = "Stock histórico por regularizar"
REGULARIZATION_LOCATION_NORMALIZED = "stock historico por regularizar"


def assign_historical_stock_to_regularization(apps, schema_editor):
    InventoryLocation = apps.get_model("inventory", "InventoryLocation")
    ProductLocationBalance = apps.get_model(
        "inventory",
        "ProductLocationBalance",
    )
    Producto = apps.get_model("inventory", "Producto")
    PendientePorRecibir = apps.get_model(
        "inventory",
        "PendientePorRecibir",
    )

    regularization_location, _ = InventoryLocation.objects.get_or_create(
        is_regularization=True,
        defaults={
            "name": REGULARIZATION_LOCATION_NAME,
            "name_normalized": REGULARIZATION_LOCATION_NORMALIZED,
            "location_type": "OTRO",
            "description": (
                "Saldo heredado anterior al control formal de ubicaciones."
            ),
            "status": "ACTIVO",
        },
    )

    balances = [
        ProductLocationBalance(
            product_id=product_id,
            location_id=regularization_location.pk,
            quantity=stock_actual,
        )
        for product_id, stock_actual in Producto.objects.filter(
            controla_stock=True,
            stock_actual__gt=0,
        ).values_list("pk", "stock_actual")
    ]
    ProductLocationBalance.objects.bulk_create(
        balances,
        ignore_conflicts=True,
    )

    PendientePorRecibir.objects.filter(
        destination_location__isnull=True
    ).update(destination_location_id=regularization_location.pk)


